style.css:
@-moz-document domain("youtube.com") {
/* =========================================
     Custom YouTube Theme: #f3edf7, #dbcfe3, Lora, Cursive, Celestial & Watched Bars
     ========================================= */

  :root,
  html[light],
  ytd-app {
    /* Replace YouTube Red & Black Accents with #dbcfe3 */
    --yt-spec-brand-background-solid: #dbcfe3 !important;
    --yt-spec-red-indicator: #dbcfe3 !important;
    --yt-spec-static-brand-red: #dbcfe3 !important;
    --yt-spec-brand-button-background: #dbcfe3 !important;
    --yt-spec-brand-link-text: #6e6873 !important;
    --yt-spec-inverted-background: #dbcfe3 !important;
    --yt-spec-static-brand-black: #dbcfe3 !important;
    --yt-spec-selected-nav-background: #dbcfe3 !important;

    /* Replace Dark Video Player Overlay Pills with Light Purple */
    --yt-spec-overlay-background-medium: rgba(243, 237, 247, 0.9) !important;
    --yt-spec-overlay-background-medium-light: rgba(243, 237, 247, 0.85) !important;
    --yt-spec-overlay-background-light: rgba(219, 207, 227, 0.85) !important;

    /* Grey Text Variables */
    --yt-spec-text-primary: #525252 !important;
    --yt-spec-text-primary-inverse: #525252 !important;
    --yt-spec-text-secondary: #757575 !important;
    --yt-spec-text-disabled: #999999 !important;
    --yt-spec-call-to-action: #636363 !important;
    --yt-spec-icon-active-other: #525252 !important;
    --yt-spec-icon-inactive: #757575 !important;

    /* Replace Main, Secondary, & Popup Backgrounds with #f3edf7 */
    --yt-spec-base-background: #f3edf7 !important;
    --yt-spec-raised-background: #f3edf7 !important;
    --yt-spec-menu-background: #f3edf7 !important;
    --yt-spec-general-background-a: #f3edf7 !important;
    --yt-spec-general-background-b: #f3edf7 !important;
    --yt-spec-general-background-c: #ebe1f2 !important;

    /* Subtle Purple-Grey for Chips, Hovers, & Dividers */
    --yt-spec-badge-chip-background: #e8def0 !important;
    --yt-spec-button-chip-background-hover: #dbcfe3 !important;
    --yt-spec-10-percent-layer: rgba(180, 155, 198, 0.25) !important;
  }

  /* =========================================
     Watched Video Thumbnail Progress Bars -> #dbcfe3
     ========================================= */

  ytd-thumbnail-overlay-resume-playback-renderer #progress,
  .ytThumbnailOverlayProgressBarHostWatchedProgressBarSegment,
  .yt-thumbnail-overlay-progress-bar-view-model__watched-progress-bar-segment,
  .ytThumbnailOverlayProgressBarHostWatchedProgressBar,
  #progress.ytd-thumbnail-overlay-resume-playback-renderer {
    background-color: #dbcfe3 !important;
    background: #dbcfe3 !important;
  }

  ytd-thumbnail-overlay-resume-playback-renderer,
  .ytThumbnailOverlayProgressBarHost {
    background-color: rgba(243, 237, 247, 0.65) !important;
  }

  /* =========================================
     Custom Darker Purple Scrollbar (#dbcfe3)
     ========================================= */

  * {
    scrollbar-width: thin !important;
    scrollbar-color: #dbcfe3 #f3edf7 !important;
  }

  ::-webkit-scrollbar {
    width: 10px !important;
    height: 10px !important;
    background-color: #f3edf7 !important;
  }

  ::-webkit-scrollbar-track {
    background-color: #f3edf7 !important;
    border-radius: 8px !important;
  }

  ::-webkit-scrollbar-thumb {
    background-color: #dbcfe3 !important;
    border-radius: 8px !important;
    border: 2px solid #f3edf7 !important;
  }

  ::-webkit-scrollbar-thumb:hover {
    background-color: #cbbad6 !important;
  }

  ::-webkit-scrollbar-corner {
    background-color: #f3edf7 !important;
  }

  /* =========================================
     Fonts: Lora & Cursive Bold (No External Imports)
     ========================================= */

  *:not(yt-icon):not(.material-icons):not([class*="icon"]) {
    font-family: 'Lora', 'Palatino', 'Georgia', serif !important;
  }

  b,
  strong,
  h1,
  h2,
  h3,
  h4,
  #video-title,
  #video-title-link,
  yt-formatted-string#video-title,
  #title.ytd-watch-metadata,
  #title.ytd-shelf-renderer,
  #guide-section-title,
  .yt-core-attributed-string--link-inherit-color[style*="font-weight: 500"],
  .yt-core-attributed-string--link-inherit-color[style*="font-weight: 600"],
  .yt-core-attributed-string--link-inherit-color[style*="font-weight: 700"],
  [style*="font-weight: 600"],
  [style*="font-weight: 700"],
  [style*="font-weight: bold"] {
    font-family: 'Cormorant Garamond', 'Snell Roundhand', 'Apple Chancery', 'Brush Script MT', cursive !important;
    font-style: italic !important;
    font-weight: 700 !important;
    letter-spacing: 0.02em !important;
  }

  /* =========================================
     Global Grey Text Color
     ========================================= */

  body,
  ytd-app,
  yt-formatted-string,
  span,
  a,
  p,
  h1,
  h2,
  h3,
  h4,
  div,
  button,
  input,
  textarea,
  #video-title,
  #channel-name,
  #metadata-line,
  #description,
  .yt-core-attributed-string {
    color: #525252 !important;
  }

  #metadata-line span,
  ytd-video-meta-block #metadata-line,
  .ytd-channel-name,
  #owner-sub-count,
  #info span {
    color: #757575 !important;
  }

  /* =========================================
     Main Page, Header, Sidebar & Pop-Ups -> #f3edf7
     ========================================= */

  html,
  body,
  ytd-app,
  #masthead-container.ytd-app,
  #masthead,
  #background.ytd-masthead,
  #contentContainer.tp-yt-app-drawer,
  #guide-inner-content.ytd-app,
  ytd-mini-guide-renderer,
  ytd-mini-guide-entry-renderer,
  #chips-wrapper.ytd-feed-filter-chip-bar-renderer {
    background-color: #f3edf7 !important;
  }

  tp-yt-iron-dropdown,
  ytd-popup-container tp-yt-iron-dropdown #contentWrapper,
  ytd-multi-page-menu-renderer,
  #header.ytd-multi-page-menu-renderer,
  #container.ytd-multi-page-menu-renderer,
  #sections.ytd-multi-page-menu-renderer,
  ytd-simple-menu-header-renderer,
  ytd-notification-renderer,
  ytd-comment-replies-renderer,
  yt-sheet-view-model,
  .ytSheetViewModelContextual,
  .yt-list-view-model-wiz {
    background-color: #f3edf7 !important;
    border-color: #dbcfe3 !important;
  }

  ytd-notification-renderer:hover,
  ytd-compact-link-renderer:hover,
  yt-list-item-view-model:hover {
    background-color: #e8def0 !important;
  }

  ytd-notification-renderer[unread] #new.ytd-notification-renderer {
    background-color: #9e82b3 !important;
  }

  /* =========================================
     Black & Selected Buttons -> #dbcfe3
     ========================================= */

  .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--filled,
  .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--tonal[aria-pressed="true"],
  .yt-spec-button-shape-next--mono[aria-selected="true"],
  .yt-spec-button-shape-next--filled[aria-pressed="true"],
  button[aria-selected="true"],
  button[aria-pressed="true"],
  ytd-subscribe-button-renderer button,
  yt-chip-cloud-chip-renderer[selected] #chip-container,
  iron-selector#chips yt-chip-cloud-chip-renderer[selected] #chip-container,
  ytChipShape[aria-selected="true"],
  .ytChipShapeChip.ytChipShapeActive,
  .ytChipShapeActive {
    background-color: #dbcfe3 !important;
    color: #525252 !important;
    border-color: #cbbad6 !important;
  }

  .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--filled:hover,
  ytd-subscribe-button-renderer button:hover,
  yt-chip-cloud-chip-renderer[selected] #chip-container:hover,
  .ytChipShapeActive:hover {
    background-color: #cbbad6 !important;
  }

  .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--filled span,
  .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--filled yt-icon,
  .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--filled svg,
  yt-chip-cloud-chip-renderer[selected] #chip-container #text,
  .ytChipShapeActive div,
  yt-icon {
    color: #525252 !important;
    fill: #525252 !important;
  }

  /* =========================================
     YouTube Logo -> Darker Purple (#dbcfe3)
     ========================================= */

  ytd-topbar-logo-renderer #logo-icon svg path[fill="#FF0000"],
  ytd-topbar-logo-renderer #logo-icon svg path[fill="#FF0033"],
  ytd-topbar-logo-renderer #logo-icon svg path[fill="#f00"],
  ytd-topbar-logo-renderer #logo-icon svg > g > path:first-child,
  ytd-topbar-logo-renderer #logo-icon svg > path:first-child,
  yt-icon.ytd-logo svg path[fill="#FF0000"],
  yt-icon.ytd-logo svg path[fill="#FF0033"],
  yt-icon.ytd-logo svg > g > path:first-child,
  yt-icon.ytd-logo svg > path:first-child,
  #logo-icon svg path[fill*="FF00"] {
    fill: #dbcfe3 !important;
  }

  /* =========================================
     Moons, Stars & Sparkles on ALL Icons
     ========================================= */

  yt-icon {
    position: relative !important;
    overflow: visible !important;
  }

  yt-icon::after {
    content: "✦";
    position: absolute !important;
    top: -3px !important;
    right: -4px !important;
    font-size: 8px !important;
    line-height: 1 !important;
    color: #8c70a1 !important;
    pointer-events: none !important;
  }

  ytd-guide-entry-renderer:nth-child(odd) yt-icon::after,
  ytd-mini-guide-entry-renderer:nth-child(odd) yt-icon::after,
  #buttons yt-icon-button:nth-child(odd) yt-icon::after {
    content: "☾" !important;
    font-size: 9px !important;
    color: #7d6291 !important;
  }

  ytd-guide-entry-renderer:nth-child(even) yt-icon::after,
  ytd-mini-guide-entry-renderer:nth-child(even) yt-icon::after,
  #buttons yt-icon-button:nth-child(even) yt-icon::after {
    content: "★" !important;
    font-size: 8px !important;
    color: #8c70a1 !important;
  }

  ytd-topbar-logo-renderer::after {
    content: "☾ ⋆⁺₊⋆ ✦";
    font-size: 14px !important;
    color: #8c70a1 !important;
    margin-left: 6px !important;
    display: inline-flex !important;
    align-items: center !important;
  }

ytd-subscribe-button-renderer button::before {
content: "★ ";
font-size: 13px !important;
color: #7d6291 !important;
margin-right: 4px !important;
}
like-button-view-model button::after,
#segmented-like-button button::after {
content: " ✧";
font-size: 13px !important;
color: #7d6291 !important;
margin-left: 4px !important;
}
yt-chip-cloud-chip-renderer[selected] #chip-container::before,
.ytChipShapeActive::before {
content: "✦ ";
font-size: 11px !important;
color: #7d6291 !important;
margin-right: 4px !important;
}
ytd-simple-menu-header-renderer #title::after {
content: "  ☾⋆⁺₊⋆";
font-size: 14px !important;
color: #8c70a1 !important;
}
/* =========================================
Light Purple Video Player Bottom Controls & Pills
========================================= */
.ytp-chrome-bottom {
background: rgba(243, 237, 247, 0.92) !important;
border-top: 1px solid #dbcfe3 !important;
border-radius: 12px 12px 0 0 !important;
padding-top: 4px !important;
}
.ytp-gradient-bottom {
background: linear-gradient(to top, rgba(243, 237, 247, 0.85), transparent) !important;
}
.ytp-chrome-controls .ytp-button,
.ytp-left-controls > *,
.ytp-right-controls,
.ytp-right-controls > *,
.ytp-volume-area,
.ytp-time-wrapper,
.ytp-time-display,
.ytp-chapter-container,
.ytp-chapter-title,
.ytp-play-button,
.ytp-next-button,
.ytp-prev-button,
.ytp-mute-button {
background-color: rgba(243, 237, 247, 0.95) !important;
background: rgba(243, 237, 247, 0.95) !important;
backdrop-filter: none !important;
box-shadow: none !important;
}
.ytp-chrome-controls .ytp-button:hover,
.ytp-volume-area:hover,
.ytp-chapter-container:hover {
background-color: #dbcfe3 !important;
background: #dbcfe3 !important;
}
.ytp-progress-list {
background-color: rgba(219, 207, 227, 0.45) !important;
}
.ytp-load-progress {
background-color: rgba(219, 207, 227, 0.75) !important;
}
.ytp-play-progress,
.ytp-scrubber-button {
background-color: #dbcfe3 !important;
box-shadow: 0 0 6px #9e82b3 !important;
}
.ytp-chrome-bottom .ytp-button,
.ytp-chrome-bottom .ytp-button svg,
.ytp-chrome-bottom .ytp-button svg path,
.ytp-volume-slider-handle,
.ytp-volume-slider-handle::before {
color: #8c70a1 !important;
fill: #8c70a1 !important;
}
.ytp-volume-slider-handle {
background-color: #dbcfe3 !important;
}
.ytp-autonav-toggle-button-container .ytp-autonav-toggle-button {
background-color: #dbcfe3 !important;
}
.ytp-time-display,
.ytp-time-display span,
.ytp-chapter-title-content,
.ytp-chapter-title-prefix {
color: #6e6873 !important;
text-shadow: none !important;
}
.ytp-chrome-bottom .ytp-button {
position: relative !important;
overflow: visible !important;
}
.ytp-play-button::after {
content: "☾";
position: absolute !important;
top: 4px !important;
right: 4px !important;
font-size: 10px !important;
color: #8c70a1 !important;
}
.ytp-next-button::after {
content: "✦";
position: absolute !important;
top: 4px !important;
right: 4px !important;
font-size: 9px !important;
color: #8c70a1 !important;
}
.ytp-mute-button::after {
content: "⋆";
position: absolute !important;
top: 4px !important;
right: 4px !important;
font-size: 11px !important;
color: #8c70a1 !important;
}
.ytp-subtitles-button::after {
content: "✧";
position: absolute !important;
top: 4px !important;
right: 4px !important;
font-size: 9px !important;
color: #8c70a1 !important;
}
.ytp-settings-button::after {
content: "★";
position: absolute !important;
top: 4px !important;
right: 4px !important;
font-size: 9px !important;
color: #8c70a1 !important;
}
.ytp-size-button::after {
content: "✦";
position: absolute !important;
top: 4px !important;
right: 4px !important;
font-size: 9px !important;
color: #8c70a1 !important;
}
.ytp-fullscreen-button::after {
content: "☾";
position: absolute !important;
top: 4px !important;
right: 4px !important;
font-size: 10px !important;
color: #8c70a1 !important;
}
.ytp-popup,
.ytp-panel,
.ytp-panel-menu,
.ytp-menuitem-label,
.ytp-menuitem-content {
background-color: #f3edf7 !important;
color: #525252 !important;
}
.ytp-menuitem:hover {
background-color: #dbcfe3 !important;
}
.ytp-settings-button.ytp-hd-quality-badge::after,
.ytp-live-badge[disabled]::before {
background-color: #dbcfe3 !important;
}
/* =========================================
Notification Badge, Search Bar & Sidebar Hovers
========================================= */
.yt-spec-icon-badge-shape--type-notification .yt-spec-icon-badge-shape__badge {
background-color: #dbcfe3 !important;
color: #525252 !important;
}
yt-chip-cloud-chip-renderer:not([selected]) #chip-container,
.ytChipShapeChip:not(.ytChipShapeActive),
#below ytd-watch-metadata #description {
background-color: #e8def0 !important;
}
#search-form #container.ytd-searchbox {
background-color: #f3edf7 !important;
border-color: #dbcfe3 !important;
}
#search-icon-legacy.ytd-searchbox {
background-color: #dbcfe3 !important;
border-color: #dbcfe3 !important;
}
ytd-guide-entry-renderer[active],
ytd-guide-entry-renderer:hover,
ytd-mini-guide-entry-renderer[is-active],
ytd-mini-guide-entry-renderer:hover {
background-color: #dbcfe3 !important;
}
}
